package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class CSVPrinter_CSVPrinter_TriageGen0Test {

    @Test
    public void testConstructor_Success() throws IOException {
        Appendable out = new StringWriter();
        CSVFormat format = CSVFormat.DEFAULT;

        CSVPrinter printer = new CSVPrinter(out, format);

        assertEquals(out, printer.getOut());
        printer.close();
    }

    @Test(expected = NullPointerException.class)
    public void testConstructor_NullOut() throws IOException {
        CSVFormat format = CSVFormat.DEFAULT;
        new CSVPrinter(null, format);
    }

    @Test(expected = NullPointerException.class)
    public void testConstructor_NullFormat() throws IOException {
        Appendable out = new StringWriter();
        new CSVPrinter(out, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructor_InvalidFormat() throws IOException {
        Appendable out = new StringWriter();
        // Creating a format that fails validation if possible, 
        // or using a mock/custom format that throws exception on validate()
        CSVFormat format = new CSVFormat.Builder()
                .setDelimiter('\0') // Some implementations might throw exception on invalid delimiter during validate()
                .build();

        // If CSVFormat.validate() is called, we rely on the implementation 
        // of validate() to throw an exception for an invalid configuration.
        // Since we cannot easily mock the final/internal behavior of CSVFormat without PowerMock,
        // we assume a scenario where validate() is triggered.
        new CSVPrinter(out, format) {
            // This is a placeholder for a scenario where format.validate() throws an exception
        };
    }
}
